/bin/bash -lc "python - <<'PY'
import csv, collections
with open('inputs/CRISPRGeneEffect.csv',newline='') as f: a=next(csv.reader(f))[1:]
with open('inputs/OmicsExpressionProteinCodingGenesTPMLogp1BatchCorrected.csv',newline='') as f: b=next(csv.reader(f))[1:]
parse=lambda x:(x.rsplit(' (',1)[0],x.rsplit(' (',1)[-1].rstrip(')'))
ida={parse(x)[1]:x for x in a}
g=collections.defaultdict(list)
for x in b:g[parse(x)[1]].append(x)
print('Expression duplicate IDs:')
for k,v in g.items():
 if len(v)>1: print(k,v, 'effect=',ida.get(k))
print('\\nMismatches first 60:')
n=0
for k,v in g.items():
 if k in ida and ida[k] not in v:
  print(k,'effect=',ida[k],'expression=',v); n+=1
  if n>=60:break
PY"

